package org.slavicmyths.hunt;

import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.phys.Vec3;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.core.BlockPos;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.registry.ModEntities;
import static org.slavicmyths.hunt.BossRules.Move;

@GameTestHolder("slavicmyths_tugarin") @PrefixGameTestTemplate(false)
public final class TugarinGameTests {
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}
        @Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(net.minecraft.server.level.ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet) { }
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener) { }
    }
    private static net.minecraft.server.level.ServerPlayer player(GameTestHelper t){var p=new net.minecraft.server.level.ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RareProbe"),net.minecraft.server.level.ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(t.absoluteVec(new Vec3(3,2,3)));p.setNoGravity(true);for(int i=0;i<61;i++)p.tick();return p;}
    private static WorldBoss boss(GameTestHelper t){WorldBoss b=ModEntities.TUGARIN_ZMEY.get().create(t.getLevel());b.moveTo(t.absoluteVec(new Vec3(4,2,4)));b.setNoAi(true);b.setNoGravity(true);t.getLevel().addFreshEntity(b);return b;}
    private static net.minecraft.world.entity.animal.Cow target(GameTestHelper t,WorldBoss b,double range){var e=EntityType.COW.create(t.getLevel());e.moveTo(b.position().add(0,0,range));e.setNoAi(true);e.setNoGravity(true);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);e.setHealth(100);t.getLevel().addFreshEntity(e);b.setTarget(e);return e;}
    private static TugarinCombat combat(WorldBoss b){try{var f=WorldBoss.class.getDeclaredMethod("tugarin");f.setAccessible(true);return (TugarinCombat)f.invoke(b);}catch(Exception e){throw new AssertionError(e);}}
    private static void ticks(WorldBoss b,int ticks){for(int i=0;i<ticks;i++){b.tickCount++;combat(b).tick();}}
    private static void begin(WorldBoss b,Move m,LivingEntity e){try{var f=TugarinCombat.class.getDeclaredMethod("begin",Move.class,LivingEntity.class);f.setAccessible(true);f.invoke(combat(b),m,e);}catch(Exception ex){throw new AssertionError(ex);}}
    @GameTest(template="empty") public static void phaseThresholdAndSingleTransformation(GameTestHelper t){var b=boss(t);var id=b.getUUID();b.setHealth(176);ticks(b,2);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.PHASE_ONE,"early transition");b.setHealth(175);ticks(b,1);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.TRANSFORMING,"50% threshold");ticks(b,58);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.TRANSFORMING,"transition shorter than 3s");ticks(b,1);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"transition did not finish");t.assertTrue(b.getHealth()==175&&b.getUUID().equals(id),"heal/entity replacement");b.setHealth(300);ticks(b,80);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"phase regression/replay");t.succeed();}
    @GameTest(template="empty") public static void damageReductionIsFinite(GameTestHelper t){var b=boss(t);b.setHealth(175);ticks(b,1);b.getAttribute(Attributes.ARMOR).setBaseValue(0);b.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);float hp=b.getHealth();b.hurt(b.damageSources().generic(),20);t.assertTrue(Math.abs(hp-b.getHealth()-3)<.001,"transform must reduce to 15%, not immunity");t.succeed();}
    @GameTest(template="empty") public static void nativeSaveLoadKeepsTrueForm(GameTestHelper t){var b=boss(t);b.setHealth(174);ticks(b,1);var n=new CompoundTag();b.saveWithoutId(n);var loaded=boss(t);loaded.load(n);t.assertTrue(loaded.getHealth()==174&&loaded.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"interrupted save must resolve true form without animation replay");ticks(loaded,65);t.assertTrue(loaded.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"save replayed transform");t.assertTrue(Math.abs(loaded.getAttributeValue(Attributes.MOVEMENT_SPEED)-.285*1.23)<.001,"speed phase bonus");t.succeed();}
    @GameTest(template="empty") public static void legacyLowHealthSaveMigrates(GameTestHelper t){var b=boss(t);b.setHealth(150);var n=new CompoundTag();b.saveWithoutId(n);n.remove("TugarinState");n.putInt("BossPhase",3);var other=boss(t);other.load(n);t.assertTrue(other.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"legacy below-half restore");t.succeed();}
    @GameTest(template="empty") public static void heavyMeleeAndWeakness(GameTestHelper t){var b=boss(t);var e=target(t,b,2);ticks(b,1);begin(b,Move.PUNCH,e);ticks(b,10);t.assertTrue(Math.abs(100-e.getHealth()-12)<.001,"unarmored melee must be 12 raw");e.setHealth(100);e.invulnerableTime=0;b.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,100));begin(b,Move.PUNCH,e);ticks(b,10);t.assertTrue(Math.abs(100-e.getHealth()-8)<.001,"weakness must reduce melee once");t.succeed();}
    @GameTest(template="empty") public static void phaseTwoDamage(GameTestHelper t){var b=boss(t);b.setHealth(174);ticks(b,60);var e=target(t,b,2);ticks(b,13);begin(b,Move.PUNCH,e);ticks(b,10);t.assertTrue(Math.abs(100-e.getHealth()-12)<.002,"phase2 raw damage 12");t.succeed();}
    @GameTest(template="empty") public static void sweepRangeAndSingleHit(GameTestHelper t){var b=boss(t);var e=target(t,b,3.5);combat(b).threat(e,1);begin(b,Move.SWEEP,e);ticks(b,14);t.assertTrue(e.getHealth()==84,"sweep range/damage");ticks(b,12);t.assertTrue(e.getHealth()==84,"sweep duplicated impact");t.succeed();}
    @GameTest(template="empty") public static void wallStopsSweep(GameTestHelper t){var b=boss(t);var e=target(t,b,3.5);combat(b).threat(e,1);for(int y=1;y<5;y++)t.getLevel().setBlock(b.blockPosition().offset(0,y-2,2),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);begin(b,Move.SWEEP,e);ticks(b,14);t.assertTrue(e.getHealth()==100,"sweep through wall");t.succeed();}
    @GameTest(template="empty") public static void breathDamageAndNoTerrainFire(GameTestHelper t){var b=boss(t);b.tugarinState(WorldBoss.TugarinState.PHASE_TWO);var e=target(t,b,6);combat(b).threat(e,1);begin(b,Move.BREATH,e);ticks(b,18);t.assertTrue(e.getHealth()==94&&e.isOnFire(),"breath cone damage/fire");t.assertTrue(t.getLevel().getBlockState(e.blockPosition()).isAir(),"terrain ignition");t.succeed();}
    @GameTest(template="empty") public static void chargeImpactLimitedToOne(GameTestHelper t){var b=boss(t);var e=target(t,b,1.8);combat(b).threat(e,1);begin(b,Move.CHARGE,e);ticks(b,11);t.assertTrue(e.getHealth()==86,"charge hit damage");ticks(b,5);t.assertTrue(e.getHealth()==86,"charge repeated impact");t.assertTrue(e.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()<=16,"long charge stun");t.succeed();}
    @GameTest(template="empty") public static void wingDiveAlwaysTerminates(GameTestHelper t){var b=boss(t);b.tugarinState(WorldBoss.TugarinState.PHASE_TWO);var e=target(t,b,7);b.setNoGravity(false);begin(b,Move.WING_DIVE,e);ticks(b,36);t.assertTrue(b.move()==Move.RECOVERY,"unbounded flight");t.assertTrue(!b.isNoGravity(),"flight left gravity disabled");t.succeed();}
    @GameTest(template="empty") public static void aggroLockAndDeadTargetSwitch(GameTestHelper t){var b=boss(t);var a=target(t,b,2);var s=EntityType.SKELETON.create(t.getLevel());s.setNoAi(true);s.moveTo(b.position().add(2,0,0));t.getLevel().addFreshEntity(s);combat(b).threat(a,6);combat(b).threat(s,7);var selected=b.getTarget();ticks(b,20);t.assertTrue(b.getTarget()==selected,"target flip during 30tick lock");selected.setHealth(0);ticks(b,1);t.assertTrue(b.getTarget()!=selected&&b.getTarget()!=null,"dead target not switched immediately");t.succeed();}
    @GameTest(template="empty") public static void schedulerSeparatesPhases(GameTestHelper t){var b=boss(t);var e=target(t,b,6);b.setOnGround(true);ticks(b,1);t.assertTrue(b.move()==Move.CHARGE,"phase1 not charge");b.setHealth(174);ticks(b,60);ticks(b,13);t.assertTrue(b.move()==Move.WING_DIVE||b.move()==Move.BREATH,"phase2 obsolete action");t.succeed();}
    @GameTest(template="empty") public static void spawnProbabilityQuarter(GameTestHelper t){int count=0;for(int x=0;x<10000;x++)if(BossRules.eligibleRegion(991,x,2,BossKind.TUGARIN))count++;t.assertTrue(count>2200&&count<2800,"expected quarter-frequency regions: "+count);t.succeed();}
    @GameTest(template="empty") public static void nativePlayerMeleeAndMultiAttacker(GameTestHelper t){var b=boss(t);var p=player(t);p.moveTo(b.position().add(0,0,2));b.setTarget(p);ticks(b,1);begin(b,Move.PUNCH,p);ticks(b,10);t.assertTrue(Math.abs(20-p.getHealth()-12)<.002,"native unarmored player damage");b.invulnerableTime=0;b.hurt(b.damageSources().playerAttack(p),10);var s=EntityType.SKELETON.create(t.getLevel());s.setNoAi(true);s.moveTo(b.position().add(2,0,0));t.getLevel().addFreshEntity(s);b.invulnerableTime=0;b.hurt(b.damageSources().mobAttack(s),8);ticks(b,20);t.assertTrue(b.getTarget()==p,"player/skeleton flip-flop");p.setHealth(0);ticks(b,1);t.assertTrue(b.getTarget()==s,"player death not switched to skeleton");t.succeed();}
    @GameTest(template="empty") public static void phaseOneCooldownBlocksChargeRepeat(GameTestHelper t){var b=boss(t);var e=target(t,b,6);b.setOnGround(true);ticks(b,1);t.assertTrue(b.move()==Move.CHARGE,"first charge");ticks(b,40);t.assertTrue(b.move()!=Move.CHARGE,"charge cooldown bypass");ticks(b,100);t.assertTrue(b.move()!=Move.CHARGE,"charge repeated inside 12s cooldown");t.succeed();}
    @GameTest(template="empty") public static void actualGuaranteedBossLoot(GameTestHelper t){var b=boss(t);var p=player(t);p.moveTo(b.position().add(0,0,2));b.hurt(p.damageSources().playerAttack(p),10000);var drops=t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,b.getBoundingBox().inflate(5));t.assertTrue(drops.stream().anyMatch(e->e.getItem().is(org.slavicmyths.registry.ModItems.TUGARINOVA_KOZHA.get())&&e.getItem().getCount()>=3),"guaranteed leather absent");t.assertTrue(drops.stream().anyMatch(e->net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(e.getItem().getItem()).getPath().equals("rune_berserker_fragment")),"guaranteed rune fragment absent");t.succeed();}
    @GameTest(template="empty",timeoutTicks=100) public static void nativeAiFinishesTransformation(GameTestHelper t){var b=boss(t);b.setNoAi(false);b.setHealth(174);t.runAfterDelay(70,()->{t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.PHASE_TWO,"real server AI goal did not finish transition");t.assertTrue(b.getHealth()==174,"native AI healed");t.succeed();});}
    @GameTest(template="empty") public static void crossingHitStartsReductionImmediately(GameTestHelper t){var b=boss(t);b.setHealth(176);b.getAttribute(Attributes.ARMOR).setBaseValue(0);b.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);b.hurt(b.damageSources().generic(),2);t.assertTrue(b.tugarinState()==WorldBoss.TugarinState.TRANSFORMING,"crossing hit deferred to later tick");b.invulnerableTime=0;float hp=b.getHealth();b.hurt(b.damageSources().generic(),20);t.assertTrue(Math.abs(hp-b.getHealth()-3)<.001,"same-frame followup bypassed reduction");t.succeed();}
    @GameTest(template="empty") public static void serpentLungeAndSmokeBurst(GameTestHelper t){var b=boss(t);b.tugarinState(WorldBoss.TugarinState.PHASE_TWO);var e=target(t,b,3.2);combat(b).threat(e,1);begin(b,Move.SERPENT_LUNGE,e);ticks(b,8);t.assertTrue(e.getHealth()==86&&e.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"lunge damage/soft control");t.assertTrue(e.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()==45,"lunge long stun");e.setHealth(100);e.invulnerableTime=0;begin(b,Move.SMOKE_BURST,e);ticks(b,14);t.assertTrue(e.getHealth()==92&&e.isOnFire(),"smoke burst damage/fire");t.assertTrue(!e.hasEffect(MobEffects.BLINDNESS),"burst blindness");t.succeed();}
    @GameTest(template="empty") public static void likhoRetainsThreePhasesAndStats(GameTestHelper t){var b=ModEntities.LIKHO_ONE_EYED.get().create(t.getLevel());t.assertTrue(b.getMaxHealth()==320&&b.getAttributeValue(Attributes.ATTACK_DAMAGE)==11,"Likho attributes altered");t.assertTrue(BossRules.phase(BossKind.LIKHO,.6F)==2&&BossRules.phase(BossKind.LIKHO,.25F)==3,"Likho phases changed");t.assertTrue(BossRules.phase(BossKind.TUGARIN,.51F)==1&&BossRules.phase(BossKind.TUGARIN,.5F)==2,"Tugarin phase utility stale");t.succeed();}
}
